import{_ as e,H as a,f as o,i as r}from"./chunks/framework.DLd0CbzH.js";const h=JSON.parse('{"title":"Global Settings","description":"Changing the interface language, accounting currency, and data rescue/reset tools in OmniCraft ERP.","frontmatter":{"title":"Global Settings","description":"Changing the interface language, accounting currency, and data rescue/reset tools in OmniCraft ERP.","order":16},"headers":[],"relativePath":"docs/global-settings.md","filePath":"docs/global-settings.md"}'),n={name:"docs/global-settings.md"};function i(s,t,l,c,u,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation Under Development</p><p><strong>Dear Users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, with regular updates and expansions, the reference materials are also being updated gradually.</p><p>At this time, please treat the documentation as a guide—it is currently incomplete, may temporarily lack descriptions for certain features, or contain minor inaccuracies.</p></div><h1 id="⚙️-global-settings-language-currency-and-security" tabindex="-1">⚙️ Global Settings: Language, Currency, and Security <a class="header-anchor" href="#⚙️-global-settings-language-currency-and-security" aria-label="Permalink to &quot;⚙️ Global Settings: Language, Currency, and Security&quot;">​</a></h1><p>Unlike <em>Workspace Settings</em>, which affect the economics of a specific business (rates, markups, overhead costs), <strong>Global Settings</strong> establish the fundamental rules of operation for the entire application and your local database.</p><p>To open them, click <strong>File ➔ Program Settings</strong> in the top menu.</p><hr><h2 id="🌍-localization-and-currency" tabindex="-1">🌍 Localization and Currency <a class="header-anchor" href="#🌍-localization-and-currency" aria-label="Permalink to &quot;🌍 Localization and Currency&quot;">​</a></h2><h3 id="_1-interface-language" tabindex="-1">1. Interface Language <a class="header-anchor" href="#_1-interface-language" aria-label="Permalink to &quot;1. Interface Language&quot;">​</a></h3><p>The program supports full interface localization. Upon its very first launch, OmniCraft ERP automatically scans your operating system&#39;s language and adapts to it. You can switch between <strong>Russian (RU)</strong> and <strong>English (EN)</strong> at any time.</p><ul><li><strong>How it works:</strong> Changing the language requires a full restart of the application so that all system windows, cash flow categories, and directories are properly translated and loaded from the dictionary databases.</li></ul><h3 id="_2-accounting-currency" tabindex="-1">2. Accounting Currency <a class="header-anchor" href="#_2-accounting-currency" aria-label="Permalink to &quot;2. Accounting Currency&quot;">​</a></h3><p>By default, the program pulls your national currency symbol from your OS regional settings (e.g., <code>₽</code>, <code>$</code>, <code>€</code>, <code>£</code>, <code>₺</code>). You can change it to any other currency using the convenient built-in search tool (just start typing the name, such as <em>“Euro”</em> or <em>“Lira”</em>).</p><div class="warning custom-block"><p class="custom-block-title">Protecting Historical Data</p><p>The currency change button is <strong>automatically locked</strong> as soon as you begin recording real transactions (the moment you register your first purchase, sale, or cash flow entry).</p><p>This is done to protect your financial reporting. If the program allowed you to switch currencies on the fly, all your previous receipts, balances, and analytical charts would instantly become a mathematical mess. <strong>What if you relocate to another country?</strong> You will need to perform an &quot;Accounting Reset&quot; (see below) to start keeping books in the new currency from a clean slate, while preserving your existing directories and recipes.</p></div><hr><h2 id="☢️-danger-zone" tabindex="-1">☢️ Danger Zone <a class="header-anchor" href="#☢️-danger-zone" aria-label="Permalink to &quot;☢️ Danger Zone&quot;">​</a></h2><p>At the bottom of the settings window, you will find tools for radical database interventions. These buttons should be used with extreme caution.</p><h3 id="🧹-accounting-reset-wiping-transaction-history" tabindex="-1">🧹 Accounting Reset (Wiping Transaction History) <a class="header-anchor" href="#🧹-accounting-reset-wiping-transaction-history" aria-label="Permalink to &quot;🧹 Accounting Reset (Wiping Transaction History)&quot;">​</a></h3><p>This tool is designed to <strong>&quot;zero out&quot; the operational memory</strong> of the business without losing its infrastructure. It is ideal if you have been using the program in a trial/test mode, recorded many test receipts, and now want to start keeping real books from a clean slate.</p><table tabindex="0"><thead><tr><th style="text-align:left;">What will be DELETED (Logs)</th><th style="text-align:left;">What will be ZEROED (Balances)</th><th style="text-align:left;">What will be SAVED (Infrastructure)</th></tr></thead><tbody><tr><td style="text-align:left;">• Entire sales history (receipts)</td><td style="text-align:left;">• Physical materials stock in warehouse</td><td style="text-align:left;">• All equipment &amp; assets (Workshop)</td></tr><tr><td style="text-align:left;">• Inventory movement logs</td><td style="text-align:left;">• Finished goods stock (Showcase)</td><td style="text-align:left;">• Materials directories &amp; supplier links</td></tr><tr><td style="text-align:left;">• Cash flow ledger (Cash Flow)</td><td style="text-align:left;">• Cash register balances &amp; Cash Flow history</td><td style="text-align:left;">• All product templates &amp; Recipes</td></tr><tr><td style="text-align:left;">• Production queue (Workbench)</td><td style="text-align:left;">• FIFO batch cost values</td><td style="text-align:left;">• Categories, pack types, global settings</td></tr></tbody></table><p>Prior to performing the wipe, the program will automatically create a shadow backup of the database. After clicking <strong>&quot;Clear History&quot;</strong> (Accounting Reset), OmniCraft will prompt an automatic reboot. You will receive a clean workshop, ready for the initial stock inventory (see <a href="./getting-started">Quick Start</a>).</p><h3 id="💥-factory-reset" tabindex="-1">💥 Factory Reset <a class="header-anchor" href="#💥-factory-reset" aria-label="Permalink to &quot;💥 Factory Reset&quot;">​</a></h3><p>This is the &quot;red pill&quot; button—the ultimate database reset. It <strong>permanently deletes absolutely everything</strong> from your local SQLite database.</p><ul><li>All tables, directories, recipes, receipts, stock balances, settings, and license keys vanish completely.</li><li>Upon the next startup, the program will generate a brand new database, exactly as if you had just downloaded and installed OmniCraft ERP for the very first time.</li></ul><div class="danger custom-block"><p class="custom-block-title">Attention!</p><p>Before using this function, <strong>always</strong> make a manual data export (<code>File ➔ Export Data ➔ Backup Database .db</code>) if there is even a slight chance you might need this information in the future. Recovering data after a factory reset without a backup file is impossible.</p></div><hr><h2 id="🔄-automatic-reboot" tabindex="-1">🔄 Automatic Reboot <a class="header-anchor" href="#🔄-automatic-reboot" aria-label="Permalink to &quot;🔄 Automatic Reboot&quot;">​</a></h2><p>Any changes in the Global Settings (changing the language, currency, or resetting accounts) require a reconfiguration of the operational memory. After saving changes, the program will prompt you to <strong>reboot now</strong> or do it later.</p><p>During the reboot, OmniCraft ERP carefully preserves your window geometry (size and position on the screen), allowing you to resume your work exactly where you left off.</p>',27)])])}const p=e(n,[["render",i]]);export{h as __pageData,p as default};
